input.newString:
// Fill background
ctx.fillStyle = 'black';
ctx.fillRect(0, 0, width, height);
// Starfield
ctx.fillStyle = 'white';
stars.forEach(s => {
  ctx.beginPath();
  ctx.arc(s.x, s.y, s.radius, 0, Math.PI * 2);
  ctx.fill();
});
// Ship draw (triangle with gradient)
ctx.save();
ctx.translate(ship.x, ship.y);
ctx.rotate(ship.angle);
const grad = ctx.createLinearGradient(-12, -6, 12, 6);
grad.addColorStop(0, '#ffdd33');
grad.addColorStop(1, '#ff8800');
ctx.fillStyle = grad;
ctx.beginPath();
ctx.moveTo(12, 0);
ctx.lineTo(-8, 6);
ctx.lineTo(-8, -6);
ctx.closePath();
ctx.fill();
ctx.restore();
// Asteroids (irregular polygons)
ctx.strokeStyle = '#888';
ctx.fillStyle = '#555';
asteroids.forEach(a => {
  ctx.beginPath();
  const shape = a.shape;
  if (shape && shape.length) {
    shape.forEach((pt, i) => {
      const x = a.x + pt.x;
      const y = a.y + pt.y;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
  } else {
    // fallback circle
    ctx.arc(a.x, a.y, a.radius, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
  }
});
// HUD

